css:
#tongsci2-2-2-2-1-inquiry .head { display: flex; align-items: flex-end; justify-content: space-between; gap: 32px; }
#tongsci2-2-2-2-1-inquiry .head .titles { display: flex; flex-direction: column; gap: 6px; }
#tongsci2-2-2-2-1-inquiry .head .pen { font-size: 44px; transform: rotate(-1.5deg); padding-bottom: 6px; white-space: nowrap; }
#tongsci2-2-2-2-1-inquiry .frame { gap: 20px; }
#tongsci2-2-2-2-1-inquiry .body { flex: 1 1 auto; min-height: 0; display: grid; grid-template-columns: 860px 1fr; gap: 48px; }
#tongsci2-2-2-2-1-inquiry .body { grid-template-rows: minmax(0, 1fr); }

